<?php
namespace App\Http\Controllers\Admin;
use App\Enums\NavigationLinkType; use App\Models\{NavigationMenu,NavigationItem,Category,CmsPage}; use App\Services\NavigationService; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class NavigationController { public function index(){return view('admin.navigation.index',['menus'=>NavigationMenu::withCount('items')->get()]);} public function edit(NavigationMenu $menu){return view('admin.navigation.edit',['menu'=>$menu->load('items'),'types'=>NavigationLinkType::cases(),'categories'=>Category::active()->ordered()->get(['id','name']),'pages'=>CmsPage::query()->orderBy('title')->get(['id','title'])]);} public function store(Request $r,NavigationMenu $menu){$d=$this->validateItem($r);$d['navigation_menu_id']=$menu->id;$d['sort_order']=$menu->items()->max('sort_order')+1;NavigationItem::create($d);app(NavigationService::class)->clear();return back()->with('status','Navigation item added.');} public function update(Request $r,NavigationMenu $menu,NavigationItem $item){abort_unless($item->navigation_menu_id===$menu->id,404);$item->update($this->validateItem($r));app(NavigationService::class)->clear();return back()->with('status','Navigation item updated.');} public function destroy(NavigationMenu $menu,NavigationItem $item){abort_unless($item->navigation_menu_id===$menu->id,404);$item->delete();app(NavigationService::class)->clear();return back();} public function reorder(Request $r,NavigationMenu $menu){$ids=$r->validate(['ids'=>'array'])['ids']??[];foreach($ids as $i=>$id)$menu->items()->whereKey($id)->update(['sort_order'=>$i]);app(NavigationService::class)->clear();return back();} private function validateItem(Request $r):array{$d=$r->validate(['label'=>'required|string|max:80','link_type'=>['required',Rule::enum(NavigationLinkType::class)],'reference_id'=>'nullable|integer','url'=>'nullable|string|max:2048','is_active'=>'nullable|boolean','open_in_new_tab'=>'nullable|boolean']); if($d['link_type']==='external' && !preg_match('/^https:\/\//i',(string)($d['url']??''))) abort(422,'Only HTTPS external URLs are allowed.'); if($d['link_type']==='route' && !array_key_exists($d['url']??'',NavigationService::ROUTES)) abort(422,'Route is not allowed.'); if($d['link_type']==='category' && !Category::whereKey($d['reference_id']??0)->exists()) abort(422,'Category is invalid.'); if($d['link_type']==='cms_page' && !CmsPage::whereKey($d['reference_id']??0)->exists()) abort(422,'CMS page is invalid.'); return $d;} }
